+fn compiler_trace_pireus_hlir(module: &HlirModule) with IO, Mut, Panic, Div, Alloc {
+    if !str_eq(read_env("SOUNIO_PIREUS_OPERATOR_TRACE"), "1") { return }
+    var fi: i64 = 0
+    while fi < module.fn_count {
+        var bi: i64 = 0
+        while bi < module.functions[fi as usize].block_count {
+            let block = &module.functions[fi as usize].blocks[bi as usize]
+            var ii: i64 = 0
+            while ii < block.instr_count {
+                let instr = &block.instrs[ii as usize]
+                if instr.operator_kind == HLIR_OPERATOR_XOR_CONVOLUTION {
+                    print("PIREUS_HLIR_TYPED operator_kind=")
+                    print_int(instr.operator_kind)
+                    print(" bits=")
+                    print_int(instr.xor_bits)
+                    print(" twist=")
+                    print_int(instr.xor_twist)
+                    print(" candidate=")
+                    print_int(instr.xor_candidate)
+                    print(" argc=")
+                    print_int(instr.call_arg_count)
+                    print(" callee_len=")
+                    print_int(instr.call_name.len)
+                    print("\n")
+                }
+                ii = ii + 1
+            }
+            bi = bi + 1
+        }
+        fi = fi + 1
+    }
+}
