 // Lower a single HLIR instruction to GPU ops and append to kernel.
+pub fn hlir_gpu_xor_contract_valid(instr: HlirInstr) -> bool {
+    instr.operator_kind == HLIR_OPERATOR_XOR_CONVOLUTION
+        && instr.xor_bits == 4
+        && instr.xor_twist == HLIR_XOR_TWIST_CAYLEY_DICKSON_SIGN
+        && instr.call_arg_count == 3
+        && instr.xor_candidate >= HLIR_XOR_CANDIDATE_AUTO
+        && instr.xor_candidate <= HLIR_XOR_CANDIDATE_GLOBAL_LOAD
+}
+
 fn hlir_instr_to_gpu_ops(kernel: GpuKernelIr, instr: HlirInstr) -> GpuKernelIr with Mut, Panic {
     var k = kernel
     let op_kind = instr.op_kind
@@ -1876,6 +1885,22 @@ fn hlir_instr_to_gpu_ops(kernel: GpuKernelIr, instr: HlirInstr) -> GpuKernelIr w
             bf.rhs_reg = instr.call_args[1]
             bf.addr_reg = instr.call_args[2]
             k = gpu_kernel_append_op(k, bf)
+        } else if hlir_gpu_xor_contract_valid(instr) {
+            // Explicit distributed ABI. One sedenion component lives in each of 16 active lanes.
+            // call_args = [pa, pb, pout]. The DGX PTX backend preserves the serial j accumulation.
+            // Malformed or target-incompatible contracts deliberately fall
+            // through without a material opcode; they cannot be reinterpreted
+            // as a nearby XOR implementation.
+            var xc = gpu_op_new()
+            xc.opcode = GpuOpcode::GpuXorConvolutionF64
+            xc.lhs_reg = instr.call_args[0]
+            xc.rhs_reg = instr.call_args[1]
+            xc.addr_reg = instr.call_args[2]
+            xc.rhs_imm = 1 << instr.xor_bits
+            // byte_offset is the foundry strategy: 0=warp shuffle, 1=direct global load.
+            xc.byte_offset = if instr.xor_candidate == HLIR_XOR_CANDIDATE_GLOBAL_LOAD { 1 } else { 0 }
+            k.max_threads = 1 << instr.xor_bits
+            k = gpu_kernel_append_op(k, xc)
         } else if hlir_name_is_ossm_oct_step_f64(cn) || hlir_name_is_ossm_sed_step_f64(cn) {
             // Full-f64 O-SSM step. call_args = [pA, pB, px, pH, pout]. Exact f64 → one GpuOctStepF64.
             var sf = gpu_op_new()
@@ -2600,6 +2625,22 @@ pub(crate) fn hlir_kernels_to_ptx(module: HlirModule) -> PtxBuf with IO, Mut, Pa
     combined
 }

+pub(crate) fn hlir_kernels_to_dgx_sm121_ptx(module: HlirModule) -> PtxBuf with IO, Mut, Panic, Div, Alloc {
+    var combined = ptx_buf_new()
+    let kcount = hlir_extract_kernel_count(module)
+    var ki: i64 = 0
+    while ki < kcount {
+        let fidx = hlir_get_kernel_index(module, ki)
+        if fidx >= 0 {
+            let gpu_kernel = hlir_function_to_gpu_kernel(module.functions[fidx as usize])
+            let ptx = gpu_lower_to_ptx_for_target(gpu_kernel, true)
+            combined = hlir_ptx_append_kernel_module(combined, ptx, ki == 0)
+        }
+        ki = ki + 1
+    }
+    combined
+}
