+}
+
+// One sedenion component per lane. Lane d computes the serially ordered sum
+// r[d] = Σ_j σ(d⊕j,j)·a[d⊕j]·b[j]. b[j] arrives from lane j via bfly(d⊕j).
+fn gpu_emit_xor_convolution_f64(paR: string, pbR: string, poutR: string) -> string with Mut, Panic, Div, Alloc {
+    var t = "    mov.u32 %r1, %tid.x;\n    setp.ge.u32 %p1, %r1, 16;\n    @%p1 bra $XCDONE;\n"
+    t = str_concat(str_concat(t, "    mul.wide.u32 %rd7, %r1, 8;\n    add.s64 %rd7, "), pbR)
+    t = str_concat(t, ", %rd7;\n    ld.global.f64 %fd2, [%rd7];\n    mov.b64 {%r2, %r3}, %fd2;\n")
+    t = str_concat(t, "    mov.f64 %fd0, 0d0000000000000000;\n    mov.u32 %r8, 0;\n$XCJ:\n")
+    t = str_concat(t, "    xor.b32 %r9, %r1, %r8;\n")
+    t = str_concat(t, "    shfl.sync.bfly.b32 %r4, %r2, %r9, 15, 65535;\n")
+    t = str_concat(t, "    shfl.sync.bfly.b32 %r5, %r3, %r9, 15, 65535;\n")
+    t = str_concat(t, "    mov.b64 %fd2, {%r4, %r5};\n")
+    t = str_concat(str_concat(t, "    mul.wide.u32 %rd7, %r9, 8;\n    add.s64 %rd7, "), paR)
+    t = str_concat(t, ", %rd7;\n    ld.global.f64 %fd1, [%rd7];\n    mul.f64 %fd1, %fd1, %fd2;\n")
+    t = str_concat(t, "    mad.lo.u32 %r10, %r1, 16, %r8;\n    mul.wide.u32 %rd7, %r10, 4;\n")
+    t = str_concat(t, "    mov.u64 %rd6, ossm_Lsgn;\n    add.s64 %rd7, %rd6, %rd7;\n")
+    t = str_concat(t, "    ld.global.f32 %f0, [%rd7];\n    cvt.f64.f32 %fd2, %f0;\n")
+    t = str_concat(t, "    mul.f64 %fd1, %fd1, %fd2;\n    add.f64 %fd0, %fd0, %fd1;\n")
+    t = str_concat(t, "    add.u32 %r8, %r8, 1;\n    setp.lt.u32 %p1, %r8, 16;\n    @%p1 bra $XCJ;\n")
+    t = str_concat(str_concat(t, "    mul.wide.u32 %rd7, %r1, 8;\n    add.s64 %rd7, "), poutR)
+    t = str_concat(t, ", %rd7;\n    st.global.f64 [%rd7], %fd0;\n$XCDONE:\n")
+    t
+}
+
+// Foundry candidate 1: preserve the same lane/output and serial accumulation order,
+// but obtain b[j] through a direct global load rather than a two-half warp shuffle.
+fn gpu_emit_xor_convolution_global_f64(paR: string, pbR: string, poutR: string) -> string with Mut, Panic, Div, Alloc {
+    var t = "    mov.u32 %r1, %tid.x;\n    setp.ge.u32 %p1, %r1, 16;\n    @%p1 bra $XCGDONE;\n"
+    t = str_concat(t, "    mov.f64 %fd0, 0d0000000000000000;\n    mov.u32 %r8, 0;\n$XCGJ:\n")
+    t = str_concat(t, "    xor.b32 %r9, %r1, %r8;\n")
+    t = str_concat(str_concat(t, "    mul.wide.u32 %rd7, %r8, 8;\n    add.s64 %rd7, "), pbR)
+    t = str_concat(t, ", %rd7;\n    ld.global.f64 %fd2, [%rd7];\n")
+    t = str_concat(str_concat(t, "    mul.wide.u32 %rd7, %r9, 8;\n    add.s64 %rd7, "), paR)
+    t = str_concat(t, ", %rd7;\n    ld.global.f64 %fd1, [%rd7];\n    mul.f64 %fd1, %fd1, %fd2;\n")
+    t = str_concat(t, "    mad.lo.u32 %r10, %r1, 16, %r8;\n    mul.wide.u32 %rd7, %r10, 4;\n")
+    t = str_concat(t, "    mov.u64 %rd6, ossm_Lsgn;\n    add.s64 %rd7, %rd6, %rd7;\n")
