+pub fn pireus_xor_zmm_plan_error(instr: IrInstr) -> i64 {
+    let xor_ctrl_base = instr.label_id & 31
+    let bcast_base = (instr.label_id >> 5) & 31
+    let twist = instr.imm_flags & 255
+    let candidate = (instr.imm_flags >> 8) & 255
+    if instr.imm_i64 != 4 { return 1 }
+    if twist != IR_XOR_TWIST_CAYLEY_DICKSON_SIGN { return 2 }
+    if candidate != IR_XOR_CANDIDATE_TWO_ZMM_INDEXED_PERMUTE { return 3 }
+    if instr.dst < 0 || instr.dst + 5 > 31 { return 4 }
+    if instr.src1 < 0 || instr.src1 + 1 > 31 { return 5 }
+    if instr.src2 < 0 || instr.src2 + 1 > 31 { return 6 }
+    if xor_ctrl_base < 0 || xor_ctrl_base + 7 > 31 { return 7 }
+    if bcast_base < 0 || bcast_base + 7 > 31 { return 8 }
+    if instr.field_idx < 0 || instr.field_idx > 15 { return 9 }
+    if pireus_zmm_ranges_overlap(instr.dst, 6, instr.src1, 2) { return 10 }
+    if pireus_zmm_ranges_overlap(instr.dst, 6, instr.src2, 2) { return 11 }
+    if pireus_zmm_ranges_overlap(instr.src1, 2, instr.src2, 2) { return 12 }
+    if pireus_zmm_ranges_overlap(xor_ctrl_base, 8, bcast_base, 8) { return 13 }
+    if pireus_zmm_ranges_overlap(xor_ctrl_base, 8, instr.dst, 6) { return 14 }
+    if pireus_zmm_ranges_overlap(xor_ctrl_base, 8, instr.src1, 2) { return 15 }
+    if pireus_zmm_ranges_overlap(xor_ctrl_base, 8, instr.src2, 2) { return 16 }
+    if pireus_zmm_ranges_overlap(bcast_base, 8, instr.dst, 6) { return 17 }
+    if pireus_zmm_ranges_overlap(bcast_base, 8, instr.src1, 2) { return 18 }
+    if pireus_zmm_ranges_overlap(bcast_base, 8, instr.src2, 2) { return 19 }
+    0
+}
