+// IrXorConvolutionS: compute all sixteen destination displacements in parallel.
+//
+// Constants:
+//   xor_ctrl_base+[0..7]   = [i xor 0, ..., i xor 7] for each i low bits
+//   bcast_base+[0..7]      = [i, i, ..., i]
+//   [sign_table_gpr+i*128] = two ZMM sign-bit vectors frozen by
+//                            xeon_avx512_xor_plan.sio
+//
+// Per i: 3 VPERMPD + 2 VMOVUPD + 2 VXORPD + 2 VFMADD231PD = 9 instructions.
+// Two initial VXORPD instructions zero the result: 146 instructions total.
+pub fn emit_xor_convolution_s(buf: CodeBuffer, instr: IrInstr) -> CodeBuffer with Mut, Panic, Div {
+    var code = buf
+    if !pireus_xor_zmm_plan_valid(instr) {
+        return emit_ud2(code)
+    }
+    let vl = 2
+    let dst_lo = instr.dst
+    let dst_hi = instr.dst + 1
+    let a_bcast = instr.dst + 2
+    let b_lo = instr.dst + 3
+    let b_hi = instr.dst + 4
+    let sign = instr.dst + 5
+    let xor_ctrl_base = instr.label_id & 31
+    let bcast_base = (instr.label_id >> 5) & 31
+    let sign_table_gpr = instr.field_idx
+
+    code = emit_evex_pd_rr_full(code, 1, 0x57, dst_lo, dst_lo, dst_lo, vl, 0, 0)
+    code = emit_evex_pd_rr_full(code, 1, 0x57, dst_hi, dst_hi, dst_hi, vl, 0, 0)
+    var i: i64 = 0
+    while i < 16 {
+        let lane = i & 7
+        let half = (i >> 3) & 1
+        let a_src = instr.src1 + half
+        let b_lo_src = instr.src2 + half
+        let b_hi_src = instr.src2 + (1 ^ half)
+        code = emit_evex_pd_rr_full(code, 2, 0x16, a_bcast, bcast_base + lane, a_src, vl, 0, 0)
+        code = emit_evex_pd_rr_full(code, 2, 0x16, b_lo, xor_ctrl_base + lane, b_lo_src, vl, 0, 0)
+        code = emit_evex_pd_rr_full(code, 2, 0x16, b_hi, xor_ctrl_base + lane, b_hi_src, vl, 0, 0)
+        code = emit_evex_pd_rm_disp32(code, 1, 0x10, sign, 0, sign_table_gpr, i * 128, vl)
+        code = emit_evex_pd_rr_full(code, 1, 0x57, b_lo, b_lo, sign, vl, 0, 0)
+        code = emit_evex_pd_rm_disp32(code, 1, 0x10, sign, 0, sign_table_gpr, i * 128 + 64, vl)
+        code = emit_evex_pd_rr_full(code, 1, 0x57, b_hi, b_hi, sign, vl, 0, 0)
+        code = emit_evex_pd_rr_full(code, 2, 0xB8, dst_lo, a_bcast, b_lo, vl, 0, 0)
+        code = emit_evex_pd_rr_full(code, 2, 0xB8, dst_hi, a_bcast, b_hi, vl, 0, 0)
+        i = i + 1
+    }
+    code
+}
+
+pub fn lower_xor_convolution_s(nc: &! NativeCompiler, instr: IrInstr) with Mut, Panic, Div {
+    var c = (*nc)
+    c.code = emit_xor_convolution_s(c.code, instr)
+    (*nc) = c
+}
